-- CORE identity and tenant foundation (subphase 1.2).
-- IDs are generated by the owning Rust application as UUIDv7.
-- PLATFORM product IDs are opaque contract references: cross-backend SQL FKs are forbidden.

RESET ROLE;
SET LOCAL ROLE core_identity_auth_schema_owner;

CREATE TABLE core_identity_auth.identities (
    id uuid PRIMARY KEY,
    email_normalized text NOT NULL UNIQUE,
    email_display text NOT NULL,
    display_name text,
    status text NOT NULL DEFAULT 'pending_verification'
        CHECK (status IN ('pending_verification', 'active', 'suspended', 'disabled')),
    email_verified_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT identities_email_canonical
        CHECK (email_normalized = lower(btrim(email_normalized))
            AND length(email_normalized) BETWEEN 3 AND 320
            AND position(' ' IN email_normalized) = 0)
);

RESET ROLE;
SET LOCAL ROLE core_tenancy_schema_owner;

CREATE TABLE core_tenancy.tenants (
    id uuid PRIMARY KEY,
    status text NOT NULL DEFAULT 'provisioning'
        CHECK (status IN ('provisioning', 'active', 'suspended', 'closed')),
    country_code char(2),
    currency_code char(3),
    locale text,
    time_zone text,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT tenants_country_code_format
        CHECK (country_code IS NULL OR country_code ~ '^[A-Z]{2}$'),
    CONSTRAINT tenants_currency_code_format
        CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$')
);

CREATE TABLE core_tenancy.organizations (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES core_tenancy.tenants(id),
    display_name text NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 200),
    country_code char(2),
    currency_code char(3),
    locale text,
    time_zone text,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (tenant_id, id),
    CONSTRAINT organizations_country_code_format
        CHECK (country_code IS NULL OR country_code ~ '^[A-Z]{2}$'),
    CONSTRAINT organizations_currency_code_format
        CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$')
);

CREATE TABLE core_tenancy.branches (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    display_name text NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 200),
    country_code char(2),
    currency_code char(3),
    locale text,
    time_zone text,
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (tenant_id, organization_id, id),
    FOREIGN KEY (tenant_id, organization_id)
        REFERENCES core_tenancy.organizations(tenant_id, id),
    CONSTRAINT branches_country_code_format
        CHECK (country_code IS NULL OR country_code ~ '^[A-Z]{2}$'),
    CONSTRAINT branches_currency_code_format
        CHECK (currency_code IS NULL OR currency_code ~ '^[A-Z]{3}$')
);

CREATE TABLE core_tenancy.tenant_memberships (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES core_tenancy.tenants(id),
    identity_id uuid NOT NULL,
    status text NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'active', 'suspended', 'revoked')),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (tenant_id, identity_id),
    UNIQUE (tenant_id, id)
);

CREATE TABLE core_tenancy.permissions (
    code text PRIMARY KEY,
    description text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT permissions_code_format CHECK (code ~ '^[a-z][a-z0-9_.-]{2,119}$')
);

INSERT INTO core_tenancy.permissions (code, description) VALUES
    ('tenant.read', 'Read the tenant security and configuration context'),
    ('tenant.manage', 'Manage tenant lifecycle settings'),
    ('membership.read', 'Read tenant membership records'),
    ('membership.manage', 'Invite, suspend, revoke and assign tenant members'),
    ('organization.manage', 'Manage organization structure'),
    ('branch.manage', 'Manage branch structure and regional overrides'),
    ('product.association.read', 'Read the tenant product association')
ON CONFLICT (code) DO NOTHING;

CREATE TABLE core_tenancy.tenant_roles (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES core_tenancy.tenants(id),
    code text NOT NULL CHECK (code ~ '^[a-z][a-z0-9_-]{1,63}$'),
    display_name text NOT NULL CHECK (length(btrim(display_name)) BETWEEN 1 AND 120),
    is_system boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, code)
);

CREATE TABLE core_tenancy.tenant_role_permissions (
    tenant_id uuid NOT NULL,
    role_id uuid NOT NULL,
    permission_code text NOT NULL REFERENCES core_tenancy.permissions(code),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (tenant_id, role_id, permission_code),
    FOREIGN KEY (tenant_id, role_id)
        REFERENCES core_tenancy.tenant_roles(tenant_id, id)
);

CREATE TABLE core_tenancy.membership_role_assignments (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    membership_id uuid NOT NULL,
    role_id uuid NOT NULL,
    scope_type text NOT NULL CHECK (scope_type IN ('tenant', 'organization', 'branch')),
    organization_id uuid,
    branch_id uuid,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    FOREIGN KEY (tenant_id, membership_id)
        REFERENCES core_tenancy.tenant_memberships(tenant_id, id),
    FOREIGN KEY (tenant_id, role_id)
        REFERENCES core_tenancy.tenant_roles(tenant_id, id),
    FOREIGN KEY (tenant_id, organization_id)
        REFERENCES core_tenancy.organizations(tenant_id, id),
    FOREIGN KEY (tenant_id, organization_id, branch_id)
        REFERENCES core_tenancy.branches(tenant_id, organization_id, id),
    CONSTRAINT membership_role_scope_shape CHECK (
        (scope_type = 'tenant' AND organization_id IS NULL AND branch_id IS NULL)
        OR (scope_type = 'organization' AND organization_id IS NOT NULL AND branch_id IS NULL)
        OR (scope_type = 'branch' AND organization_id IS NOT NULL AND branch_id IS NOT NULL)
    )
);

CREATE INDEX membership_role_assignments_actor_idx
    ON core_tenancy.membership_role_assignments (tenant_id, membership_id);
CREATE INDEX membership_role_assignments_scope_idx
    ON core_tenancy.membership_role_assignments (tenant_id, organization_id, branch_id);

CREATE TABLE core_tenancy.tenant_products (
    tenant_id uuid NOT NULL REFERENCES core_tenancy.tenants(id),
    product_id uuid NOT NULL,
    product_config_version integer NOT NULL CHECK (product_config_version > 0),
    association_status text NOT NULL
        CHECK (association_status IN ('pending', 'active', 'suspended', 'revoked')),
    validated_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (tenant_id, product_id)
);

RESET ROLE;
SET LOCAL ROLE core_identity_auth_schema_owner;

CREATE TABLE core_identity_auth.security_audit_events (
    id uuid PRIMARY KEY,
    actor_id uuid,
    tenant_id uuid,
    action text NOT NULL CHECK (length(action) BETWEEN 3 AND 120),
    target_type text,
    target_id uuid,
    outcome text NOT NULL CHECK (outcome IN ('success', 'denied', 'failure')),
    correlation_id uuid NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(metadata) = 'object'),
    occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX security_audit_tenant_time_idx
    ON core_identity_auth.security_audit_events (tenant_id, occurred_at DESC)
    WHERE tenant_id IS NOT NULL;
CREATE INDEX security_audit_actor_time_idx
    ON core_identity_auth.security_audit_events (actor_id, occurred_at DESC)
    WHERE actor_id IS NOT NULL;

-- Tenant-scoped policies and grants are applied by the tenancy schema owner.
RESET ROLE;
SET LOCAL ROLE core_tenancy_schema_owner;

-- Every tenant-scoped relation is isolated in PostgreSQL, not only in application queries.
DO $$
DECLARE
    table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'organizations',
        'branches',
        'tenant_memberships',
        'tenant_roles',
        'tenant_role_permissions',
        'membership_role_assignments',
        'tenant_products'
    ]
    LOOP
        EXECUTE format('ALTER TABLE core_tenancy.%I ENABLE ROW LEVEL SECURITY', table_name);
        EXECUTE format('ALTER TABLE core_tenancy.%I FORCE ROW LEVEL SECURITY', table_name);
        EXECUTE format(
            'CREATE POLICY %I ON core_tenancy.%I USING (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::uuid)',
            table_name || '_tenant_scope',
            table_name
        );
    END LOOP;
END
$$;

ALTER TABLE core_tenancy.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE core_tenancy.tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenants_tenant_scope ON core_tenancy.tenants
    USING (id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

GRANT USAGE ON SCHEMA core_tenancy TO core_tenancy_runtime;
GRANT SELECT, INSERT, UPDATE ON
    core_tenancy.tenants,
    core_tenancy.organizations,
    core_tenancy.branches,
    core_tenancy.tenant_memberships,
    core_tenancy.tenant_roles,
    core_tenancy.tenant_role_permissions,
    core_tenancy.membership_role_assignments,
    core_tenancy.tenant_products
TO core_tenancy_runtime;
GRANT DELETE ON core_tenancy.organizations, core_tenancy.branches TO core_tenancy_runtime;
GRANT SELECT ON core_tenancy.permissions TO core_tenancy_runtime;

-- Global identity and security-audit policies belong to the identity schema owner.
RESET ROLE;
SET LOCAL ROLE core_identity_auth_schema_owner;

ALTER TABLE core_identity_auth.identities ENABLE ROW LEVEL SECURITY;
ALTER TABLE core_identity_auth.identities FORCE ROW LEVEL SECURITY;
CREATE POLICY identities_actor_scope ON core_identity_auth.identities
    USING (id = NULLIF(current_setting('app.actor_id', true), '')::uuid)
    WITH CHECK (id = NULLIF(current_setting('app.actor_id', true), '')::uuid);

ALTER TABLE core_identity_auth.security_audit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE core_identity_auth.security_audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY security_audit_scope ON core_identity_auth.security_audit_events
    USING (
        (tenant_id IS NOT NULL
            AND tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
        OR (tenant_id IS NULL
            AND actor_id = NULLIF(current_setting('app.actor_id', true), '')::uuid)
    )
    WITH CHECK (
        (tenant_id IS NOT NULL
            AND tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
        OR (tenant_id IS NULL
            AND actor_id = NULLIF(current_setting('app.actor_id', true), '')::uuid)
    );

GRANT USAGE ON SCHEMA core_identity_auth TO core_identity_auth_runtime;
GRANT SELECT, INSERT, UPDATE ON core_identity_auth.identities TO core_identity_auth_runtime;
GRANT SELECT, INSERT ON core_identity_auth.security_audit_events TO core_identity_auth_runtime;

COMMENT ON TABLE core_identity_auth.identities IS
    'Global human identity owned by CORE; never grants tenant or product access by itself.';
COMMENT ON TABLE core_identity_auth.security_audit_events IS
    'Append-only security audit evidence; sensitive values and raw credentials are prohibited in metadata.';

RESET ROLE;
SET LOCAL ROLE core_tenancy_schema_owner;

COMMENT ON TABLE core_tenancy.tenant_memberships IS
    'Tenant-scoped relationship between a global identity and one tenant; authorization is evaluated per request.';
COMMENT ON TABLE core_tenancy.tenant_products IS
    'CORE-owned technical tenant/product association; product_id and version are validated through PLATFORM contracts, never SQL joins.';
COMMENT ON TABLE core_tenancy.permissions IS
    'Global, non-tenant permission vocabulary. Tenant roles bind these codes to scoped memberships.';
